WITH base AS (SELECT *, CASE WHEN monthly_fee >= 238 THEN 'High' WHEN monthly_fee >= 104 THEN 'Medium' ELSE 'Low' END AS monthly_fee_band FROM subscriptions WHERE MONTH(start_date) IN (2, 7, 9)), Summary AS (SELECT plan, ROUND(AVG(monthly_fee), 2) AS avg_monthly_fee, MIN(monthly_fee) AS min_monthly_fee FROM base GROUP BY plan) SELECT plan, avg_monthly_fee, min_monthly_fee FROM Summary ORDER BY plan;
